// Taken from https://stackoverflow.com/a/36328890
const multilineCommentsRE =
	/\/\*[^*]*\*+(?:[^/*][^*]*\*+)*\//g;
const licenseCommentsRE =
	/MIT License|MIT license|BSD license/;
const consecutiveNewlinesRE = /\n{2,}/g;
const identifierWithTrailingDollarRE = /\b(\w+)\$\d+\b/g;

/**
 * Replace specific identifiers with a more readable name, grouped by
 * the module that imports the identifier as a named import alias
 */
const identifierReplacements: Record<
	string,
	Record<string, string>
> = {
	"vite/module-runner": {
		FetchResult$1: "moduleRunner_FetchResult",
	},
	rolldown: {
		Plugin$1: "Rolldown.Plugin",
		TransformResult$1: "Rolldown.TransformResult",
	},
	"rolldown/utils": {
		TransformOptions$1: "rolldown_utils_TransformOptions",
		TransformResult$2: "rolldown_utils_TransformResult",
		ESTree$1: "rolldown_utils_ESTree",
	},
	"node:http": {
		Server$1: "http.Server",
		IncomingMessage$1: "http.IncomingMessage",
	},
	"node:https": {
		Server$2: "HttpsServer",
		ServerOptions$2: "HttpsServerOptions",
	},
	"node:url": {
		URL$1: "url_URL",
	},
	"#types/hmrPayload": {
		CustomPayload$1: "hmrPayload_CustomPayload",
		HotPayload$1: "hmrPayload_HotPayload",
	},
	"#types/customEvent": {
		InferCustomEventPayload$1:
			"hmrPayload_InferCustomEventPayload",
	},
	"#types/internal/esbuildOptions": {
		EsbuildTransformOptions$1:
			"esbuildOptions_EsbuildTransformOptions",
	},
	"#types/internal/lightningcssOptions": {
		LightningCSSOptions$1:
			"lightningcssOptions_LightningCSSOptions",
	},
	postcss: {
		Plugin$2: "PostCSS.Plugin",
	},
