const needsEscapeRegEx = /[\n\r'\\\u2028\u2029]/;
const quoteNewlineRegEx = /([\n\r'\u2028\u2029])/g;
const backSlashRegEx = /\\/g;

function escapeId(id: string): string {
	if (!needsEscapeRegEx.test(id)) return id;
	return id
		.replace(backSlashRegEx, "\\\\")
		.replace(quoteNewlineRegEx, "\\$1");
}

const getResolveUrl = (path: string, URL = "URL") =>
	`new ${URL}(${path}).href`;

const getRelativeUrlFromDocument = (
	relativePath: string,
	umd = false,
) =>
	getResolveUrl(
		`'${escapeId(partialEncodeURIPath(relativePath))}', ${
			umd
				? `typeof document === 'undefined' ? location.href : `
				: ""
		}document.currentScript && document.currentScript.tagName.toUpperCase() === 'SCRIPT' && document.currentScript.src || document.baseURI`,
	);

const getFileUrlFromFullPath = (path: string) =>
	`require('u' + 'rl').pathToFileURL(${path}).href`;

const getFileUrlFromRelativePath = (path: string) =>
	getFileUrlFromFullPath(
		`__dirname + '/${escapeId(path)}'`,
	);

const relativeUrlMechanisms: Record<
	InternalModuleFormat,
	(relativePath: string) => string
> = {
	// amd: (relativePath) => {
	//   if (relativePath[0] !== '.') relativePath = './' + relativePath
	//   return getResolveUrl(
	//     `require.toUrl('${escapeId(relativePath)}'), document.baseURI`,
	//   )
	// },
	cjs: (relativePath) =>
		`(typeof document === 'undefined' ? ${getFileUrlFromRelativePath(
			relativePath,
		)} : ${getRelativeUrlFromDocument(relativePath)})`,
	es: (relativePath) =>
		getResolveUrl(
			`'${escapeId(partialEncodeURIPath(relativePath))}', import.meta.url`,
		),
	iife: (relativePath) =>
		getRelativeUrlFromDocument(relativePath),
	// NOTE: make sure rollup generate `module` params
	// system: (relativePath) =>
	//   getResolveUrl(
	//     `'${escapeId(partialEncodeURIPath(relativePath))}', module.meta.url`,
	//   ),
	umd: (relativePath) =>
		`(typeof document === 'undefined' && typeof location === 'undefined' ? ${getFileUrlFromRelativePath(
			relativePath,
		)} : ${getRelativeUrlFromDocument(relativePath, true)})`,
};
/* end of copy */

const customRelativeUrlMechanisms = {
	...relativeUrlMechanisms,
	"worker-iife": (relativePath) =>
		getResolveUrl(
			`'${escapeId(partialEncodeURIPath(relativePath))}', self.location.href`,
		),
} as const satisfies Record<
	string,
	(relativePath: string) => string
>;

export type RenderBuiltAssetUrl = (
	filename: string,
	type: {
		type: "asset" | "public";
		hostId: string;
		hostType: "js" | "css" | "html";
		ssr: boolean;
	},
) =>
	| string
	| { relative?: boolean; runtime?: string }
	| undefined;

export function toOutputFilePathInJS(
	environment: PartialEnvironment,
	filename: string,
	type: "asset" | "public",
	hostId: string,
	hostType: "js" | "css" | "html",
	toRelative: (
		filename: string,
		hostType: string,
	) => string | { runtime: string },
): string | { runtime: string } {
	const { experimental, base, decodedBase } =
		environment.config;
	const ssr = environment.config.consumer === "server"; // was !!environment.config.build.ssr
	const { renderBuiltUrl } = experimental;
	let relative = base === "" || base === "./";
	if (renderBuiltUrl) {
		const result = renderBuiltUrl(filename, {
			hostId,
			hostType,
			type,
			ssr,
		});
		if (typeof result === "object") {
			if (result.runtime) {
				return { runtime: result.runtime };
			}
			if (typeof result.relative === "boolean") {
				relative = result.relative;
			}
		} else if (result) {
			return result;
		}
	}
	if (relative && !ssr) {
		return toRelative(filename, hostId);
	}
	return joinUrlSegments(decodedBase, filename);
}

export function createToImportMetaURLBasedRelativeRuntime(
	format: InternalModuleFormat,
	isWorker: boolean,
): (
	filename: string,
	importer: string,
) => { runtime: string } {
	const formatLong =
		isWorker && format === "iife" ? "worker-iife" : format;
	const toRelativePath =
		customRelativeUrlMechanisms[formatLong];
	return (filename, importer) => ({
		runtime: toRelativePath(
			path.posix.relative(path.dirname(importer), filename),
		),
	});
}

export function toOutputFilePathWithoutRuntime(
	filename: string,
	type: "asset" | "public",
	hostId: string,
	hostType: "js" | "css" | "html",
	config: ResolvedConfig,
	toRelative: (filename: string, hostId: string) => string,
): string {
	const { renderBuiltUrl } = config.experimental;
	let relative = config.base === "" || config.base === "./";
	if (renderBuiltUrl) {
		const result = renderBuiltUrl(filename, {
			hostId,
			hostType,
			type,
			ssr: !!config.build.ssr,
		});
		if (typeof result === "object") {
			if (result.runtime) {
				throw new Error(
					`{ runtime: "${result.runtime}" } is not supported for assets in ${hostType} files: ${filename}`,
				);
			}
			if (typeof result.relative === "boolean") {
				relative = result.relative;
			}
		} else if (result) {
			return result;
		}
	}
	if (relative && !config.build.ssr) {
		return toRelative(filename, hostId);
	} else {
		return joinUrlSegments(config.decodedBase, filename);
	}
}

export const toOutputFilePathInCss: typeof toOutputFilePathWithoutRuntime =
	toOutputFilePathWithoutRuntime;
export const toOutputFilePathInHtml: typeof toOutputFilePathWithoutRuntime =
	toOutputFilePathWithoutRuntime;

export class BuildEnvironment extends BaseEnvironment {
	mode = "build" as const;

	isBuilt = false;
	constructor(
		name: string,
		config: ResolvedConfig,
		setup?: {
			options?: EnvironmentOptions;
		},
	) {
		let options = config.environments[name];
		if (!options) {
			throw new Error(
				`Environment "${name}" is not defined in the config.`,
			);
		}
		if (setup?.options) {
			options = mergeConfig(
				options,
				setup.options,
			) as ResolvedEnvironmentOptions;
		}
		super(name, config, options);
	}

	async init(): Promise<void> {
		if (this._initiated) {
			return;
		}
		this._initiated = true;
	}
}

export interface ViteBuilder {
	environments: Record<string, BuildEnvironment>;
	config: ResolvedConfig;
	buildApp(): Promise<void>;
	build(
		environment: BuildEnvironment,
	): Promise<
		RolldownOutput | RolldownOutput[] | RolldownWatcher
	>;
	runDevTools(): Promise<void>;
}

export interface BuilderOptions {
	/**
	 * Whether to share the config instance among environments to align with the behavior of dev server.
	 *
	 * @default false
	 * @experimental
	 */
	sharedConfigBuild?: boolean;
	/**
	 * Whether to share the plugin instances among environments to align with the behavior of dev server.
	 *
	 * @default false
	 * @experimental
	 */
	sharedPlugins?: boolean;
	buildApp?: (builder: ViteBuilder) => Promise<void>;
}

const _builderOptionsDefaults = Object.freeze({
	sharedConfigBuild: false,
	sharedPlugins: false,
	// buildApp
} satisfies BuilderOptions);
export const builderOptionsDefaults: Readonly<
	Partial<BuilderOptions>
> = _builderOptionsDefaults;

export function resolveBuilderOptions(
	options: BuilderOptions | undefined,
): ResolvedBuilderOptions | undefined {
	if (!options) return;
	return mergeWithDefaults(
		{
			..._builderOptionsDefaults,
			buildApp: async () => {},
		},
		options,
	);
}

export type ResolvedBuilderOptions =
	Required<BuilderOptions>;

/**
 * Creates a ViteBuilder to orchestrate building multiple environments.
 * @experimental
 */
export async function createBuilder(
	inlineConfig: InlineConfig = {},
	useLegacyBuilder: null | boolean = false,
): Promise<ViteBuilder> {
	const patchConfig = (resolved: ResolvedConfig) => {
		if (!(useLegacyBuilder ?? !resolved.builder)) return;

		// Until the ecosystem updates to use `environment.config.build` instead of `config.build`,
		// we need to make override `config.build` for the current environment.
		// We can deprecate `config.build` in ResolvedConfig and push everyone to upgrade, and later
		// remove the default values that shouldn't be used at all once the config is resolved
		const environmentName = resolved.build.ssr
			? "ssr"
			: "client";
		(resolved.build as ResolvedBuildOptions) = {
			...resolved.environments[environmentName].build,
		};
	};
	const config = await resolveConfigToBuild(
		inlineConfig,
		patchConfig,
	);
	useLegacyBuilder ??= !config.builder;
	const configBuilder =
		config.builder ?? resolveBuilderOptions({})!;

	const environments: Record<string, BuildEnvironment> = {};

	const builder: ViteBuilder = {
		environments,
		config,
		async buildApp() {
			const pluginContext = new BasicMinimalPluginContext(
				{ ...basePluginContextMeta, watchMode: false },
				config.logger,
			);

			// order 'pre' and 'normal' hooks are run first, then config.builder.buildApp, then 'post' hooks
			let configBuilderBuildAppCalled = false;
			for (const p of config.getSortedPlugins("buildApp")) {
				const hook = p.buildApp;
				if (
					!configBuilderBuildAppCalled &&
					typeof hook === "object" &&
					hook.order === "post"
				) {
					configBuilderBuildAppCalled = true;
					await configBuilder.buildApp(builder);
				}
				const handler = getHookHandler(hook);
				await handler.call(pluginContext, builder);
			}
			if (!configBuilderBuildAppCalled) {
				await configBuilder.buildApp(builder);
			}
			// fallback to building all environments if no environments have been built
			if (
				Object.values(builder.environments).every(
					(environment) => !environment.isBuilt,
				)
			) {
				for (const environment of Object.values(
					builder.environments,
				)) {
					await builder.build(environment);
				}
			}
		},
		async build(
			environment: BuildEnvironment,
		): Promise<
			RolldownOutput | RolldownOutput[] | RolldownWatcher
		> {
			const output = await buildEnvironment(environment);
			environment.isBuilt = true;
			return output;
		},
		async runDevTools() {
			if (config.devtools) {
				try {
					const { runDevTools } = await import(
						"@vitejs/devtools/integration"
					);
					await runDevTools(builder);
				} catch (e) {
					config.logger.error(
						colors.red(
							`Failed to run Vite DevTools: ${e?.message || e?.stack}`,
						),
						{ error: e },
					);
				}
			}
		},
	};

	async function setupEnvironment(
		name: string,
		config: ResolvedConfig,
	) {
		const environment =
			await config.build.createEnvironment(name, config);
		await environment.init();
		environments[name] = environment;
	}

	if (useLegacyBuilder) {
		await setupEnvironment(
			config.build.ssr ? "ssr" : "client",
			config,
		);
	} else {
		const environmentConfigs: [string, ResolvedConfig][] =
			[];
		for (const environmentName of Object.keys(
			config.environments,
		)) {
			// We need to resolve the config again so we can properly merge options
			// and get a new set of plugins for each build environment. The ecosystem
			// expects plugins to be run for the same environment once they are created
			// and to process a single bundle at a time (contrary to dev mode where
			// plugins are built to handle multiple environments concurrently).
			let environmentConfig = config;
			if (!configBuilder.sharedConfigBuild) {
				const patchConfig = (resolved: ResolvedConfig) => {
					// Until the ecosystem updates to use `environment.config.build` instead of `config.build`,
					// we need to make override `config.build` for the current environment.
					// We can deprecate `config.build` in ResolvedConfig and push everyone to upgrade, and later
					// remove the default values that shouldn't be used at all once the config is resolved
					(resolved.build as ResolvedBuildOptions) = {
						...resolved.environments[environmentName].build,
					};
				};
				const patchPlugins = (
					resolvedPlugins: Plugin[],
				) => {
					// Force opt-in shared plugins
					let j = 0;
					for (let i = 0; i < resolvedPlugins.length; i++) {
						const environmentPlugin = resolvedPlugins[i];
						if (
							configBuilder.sharedPlugins ||
							environmentPlugin.sharedDuringBuild
						) {
							for (
								let k = j;
								k < config.plugins.length;
								k++
							) {
								if (
									environmentPlugin.name ===
									config.plugins[k].name
								) {
									resolvedPlugins[i] = config.plugins[k];
									j = k + 1;
									break;
								}
							}
						}
					}
				};
				environmentConfig = await resolveConfigToBuild(
					inlineConfig,
					patchConfig,
					patchPlugins,
				);
			}
			environmentConfigs.push([
				environmentName,
				environmentConfig,
			]);
		}
		await Promise.all(
			environmentConfigs.map(
				async ([environmentName, environmentConfig]) =>
					await setupEnvironment(
						environmentName,
						environmentConfig,
					),
			),
		);
	}

	return builder;
}

export type BuildAppHook = (
	this: MinimalPluginContextWithoutEnvironment,
	builder: ViteBuilder,
) => Promise<void>;

import type {
	CustomPluginOptions,
	ImportKind,
	LoadResult,
	MinimalPluginContext,
	ModuleType,
	ModuleTypeFilter,
	ObjectHook,
	PluginContext,
	PluginContextMeta,
	ResolveIdResult,
	Plugin as RolldownPlugin,
	RolldownMagicString,
	TransformPluginContext,
	TransformResult,
} from "rolldown";
import type { ESTree } from "rolldown/utils";
import type { PartialEnvironment } from "./baseEnvironment";
import type { BuildAppHook } from "./build";
import type {
	ConfigEnv,
	EnvironmentOptions,
	ResolvedConfig,
	UserConfig,
} from "./config";
import type { Environment } from "./environment";
import type { IndexHtmlTransform } from "./plugins/html";
import type { StringFilter } from "./plugins/pluginFilter";
import type {
	ClosePreviewServerHook,
	PreviewServerHook,
} from "./preview";
import type { CloseServerHook, ServerHook } from "./server";
import type { DevEnvironment } from "./server/environment";
import type {
	HmrContext,
	HotUpdateOptions,
} from "./server/hmr";
import type { ModuleNode } from "./server/mixedModuleGraph";
import type { EnvironmentModuleNode } from "./server/moduleGraph";
import { arraify, asyncFlatten } from "./utils";

/**
 * Vite plugins extends the Rollup plugin interface with a few extra
 * vite-specific options. A valid vite plugin is also a valid Rollup plugin.
 * On the contrary, a Rollup plugin may or may NOT be a valid vite universal
 * plugin, since some Rollup features do not make sense in an unbundled
 * dev server context. That said, as long as a rollup plugin doesn't have strong
 * coupling between its bundle phase and output phase hooks then it should
 * just work (that means, most of them).
 *
 * By default, the plugins are run during both serve and build. When a plugin
 * is applied during serve, it will only run **non output plugin hooks** (see
 * rollup type definition of {@link rollup#PluginHooks}). You can think of the
 * dev server as only running `const bundle = rollup.rollup()` but never calling
 * `bundle.generate()`.
 *
 * A plugin that expects to have different behavior depending on serve/build can
 * export a factory function that receives the command being run via options.
 *
 * If a plugin should be applied only for server or build, a function format
 * config file can be used to conditional determine the plugins to use.
 *
 * The current environment can be accessed from the context for the all non-global
 * hooks (it is not available in config, configResolved, configureServer, etc).
 * It can be a dev, build, or scan environment.
 * Plugins can use this.environment.mode === 'dev' to guard for dev specific APIs.
 */

export interface PluginContextExtension {
	/**
	 * Vite-specific environment instance
	 */
	environment: Environment;
}

export interface PluginContextMetaExtension {
	viteVersion: string;
}

export interface ConfigPluginContext
	extends Omit<
		MinimalPluginContext,
		"meta" | "environment"
	> {
	meta: Omit<PluginContextMeta, "watchMode">;
}

export interface MinimalPluginContextWithoutEnvironment
	extends Omit<MinimalPluginContext, "environment"> {}

// Augment Rolldown types to have the PluginContextExtension
declare module "rolldown" {
	export interface MinimalPluginContext
		extends PluginContextExtension {}
	export interface PluginContextMeta
		extends PluginContextMetaExtension {}
}

/**
 * There are two types of plugins in Vite. App plugins and environment plugins.
 * Environment Plugins are defined by a constructor function that will be called
 * once per each environment allowing users to have completely different plugins
 * for each of them. The constructor gets the resolved environment after the server
 * and builder has already been created simplifying config access and cache
 * management for environment specific plugins.
 * Environment Plugins are closer to regular rollup plugins. They can't define
 * app level hooks (like config, configResolved, configureServer, etc).
 */
export interface Plugin<A = any> extends RolldownPlugin<A> {
	/**
	 * Perform custom handling of HMR updates.
	 * The handler receives an options containing changed filename, timestamp, a
	 * list of modules affected by the file change, and the dev server instance.
	 *
	 * - The hook can return a filtered list of modules to narrow down the update.
	 *   e.g. for a Vue SFC, we can narrow down the part to update by comparing
	 *   the descriptors.
	 *
	 * - The hook can also return an empty array and then perform custom updates
	 *   by sending a custom hmr payload via environment.hot.send().
	 *
	 * - If the hook doesn't return a value, the hmr update will be performed as
	 *   normal.
	 */
	hotUpdate?: ObjectHook<
		(
			this: MinimalPluginContext & {
				environment: DevEnvironment;
			},
			options: HotUpdateOptions,
		) =>
			| Array<EnvironmentModuleNode>
			| void
			| Promise<Array<EnvironmentModuleNode> | void>
	>;

	/**
	 * extend hooks with ssr flag
	 */
	resolveId?: ObjectHook<
		(
			this: PluginContext,
			source: string,
			importer: string | undefined,
			options: {
				kind?: ImportKind;
				custom?: CustomPluginOptions;
				ssr?: boolean | undefined;
				/**
				 * @internal
				 */
				scan?: boolean | undefined;
				isEntry: boolean;
			},
		) => Promise<ResolveIdResult> | ResolveIdResult,
		{ filter?: { id?: StringFilter<RegExp> } }
	>;
	load?: ObjectHook<
		(
			this: PluginContext,
			id: string,
			options?: {
				ssr?: boolean | undefined;
			},
		) => Promise<LoadResult> | LoadResult,
		{ filter?: { id?: StringFilter } }
	>;
	transform?: ObjectHook<
		(
			this: TransformPluginContext,
			code: string,
			id: string,
			options?: {
				moduleType: ModuleType;
				ssr?: boolean | undefined;
				/**
				 * A lazily-created MagicString instance for the module's code.
				 * Only available during build.
				 * @experimental
				 */
				magicString?: RolldownMagicString | undefined;
				/**
				 * The lazily-parsed AST of the module's code.
				 * Only available during build.
				 * @experimental
				 */
				ast?: ESTree.Program | undefined;
			},
		) => Promise<TransformResult> | TransformResult,
		{
			filter?: {
				id?: StringFilter;
				code?: StringFilter;
				moduleType?: ModuleTypeFilter;
			};
		}
	>;
	/**
	 * Opt-in this plugin into the shared plugins pipeline.
	 * For backward-compatibility, plugins are re-recreated for each environment
	 * during `vite build --app`
	 * We have an opt-in per plugin, and a general `builder.sharedPlugins`
	 * In a future major, we'll flip the default to be shared by default
	 * @experimental
	 */
	sharedDuringBuild?: boolean;
	/**
	 * Opt-in this plugin into per-environment buildStart and buildEnd during dev.
	 * For backward-compatibility, the buildStart hook is called only once during
	 * dev, for the client environment. Plugins can opt-in to be called
	 * per-environment, aligning with the build hook behavior.
	 * @experimental
	 */
	perEnvironmentStartEndDuringDev?: boolean;
	/**
	 * Opt-in this plugin into per-environment watchChange during dev.
	 * For backward-compatibility, the watchChange hook is called only once during
	 * dev, for the client environment. Plugins can opt-in to be called
	 * per-environment, aligning with the watchChange hook behavior.
	 * @experimental
	 */
	perEnvironmentWatchChangeDuringDev?: boolean;
	/**
	 * Enforce plugin invocation tier similar to webpack loaders. Hooks ordering
	 * is still subject to the `order` property in the hook object.
	 *
	 * Plugin invocation order:
	 * - alias resolution
	 * - `enforce: 'pre'` plugins
	 * - vite core plugins
	 * - normal plugins
	 * - vite build plugins
	 * - `enforce: 'post'` plugins
	 * - vite build post plugins
	 */
	enforce?: "pre" | "post";
	/**
	 * Apply the plugin only for serve or build, or on certain conditions.
	 */
	apply?:
		| "serve"
		| "build"
		| ((
				this: void,
				config: UserConfig,
				env: ConfigEnv,
		  ) => boolean);
	/**
	 * Define environments where this plugin should be active
	 * By default, the plugin is active in all environments
	 * @experimental
	 */
	applyToEnvironment?: (
		environment: PartialEnvironment,
	) => boolean | Promise<boolean> | PluginOption;
	/**
	 * Modify vite config before it's resolved. The hook can either mutate the
	 * passed-in config directly, or return a partial config object that will be
	 * deeply merged into existing config.
	 *
	 * Note: User plugins are resolved before running this hook so injecting other
	 * plugins inside  the `config` hook will have no effect.
	 */
	config?: ObjectHook<
		(
			this: ConfigPluginContext,
			config: UserConfig,
			env: ConfigEnv,
		) =>
			| Omit<UserConfig, "plugins">
			| null
			| void
			| Promise<Omit<UserConfig, "plugins"> | null | void>
	>;
	/**
	 * Modify environment configs before it's resolved. The hook can either mutate the
	 * passed-in environment config directly, or return a partial config object that will be
	 * deeply merged into existing config.
	 * This hook is called for each environment with a partially resolved environment config
	 * that already accounts for the default environment config values set at the root level.
	 * If plugins need to modify the config of a given environment, they should do it in this
	 * hook instead of the config hook. Leaving the config hook only for modifying the root
	 * default environment config.
	 */
	configEnvironment?: ObjectHook<
		(
			this: ConfigPluginContext,
			name: string,
			config: EnvironmentOptions,
			env: ConfigEnv & {
				/**
				 * Whether this environment is SSR environment and `ssr.target` is set to `'webworker'`.
				 * Only intended to be used for backward compatibility.
				 */
				isSsrTargetWebworker?: boolean;
			},
		) =>
			| EnvironmentOptions
			| null
			| void
			| Promise<EnvironmentOptions | null | void>
	>;
	/**
	 * Use this hook to read and store the final resolved vite config.
	 */
	configResolved?: ObjectHook<
		(
			this: MinimalPluginContextWithoutEnvironment,
			config: ResolvedConfig,
		) => void | Promise<void>
	>;
	/**
	 * Configure the vite server. The hook receives the {@link ViteDevServer}
	 * instance. This can also be used to store a reference to the server
	 * for use in other hooks.
	 *
	 * The hooks will be called before internal middlewares are applied. A hook
	 * can return a post hook that will be called after internal middlewares
	 * are applied. Hook can be async functions and will be called in series.
	 */
	configureServer?: ObjectHook<ServerHook>;
	/**
	 * Configure the preview server. The hook receives the {@link PreviewServer}
	 * instance. This can also be used to store a reference to the server
	 * for use in other hooks.
	 *
	 * The hooks are called before other middlewares are applied. A hook can
	 * return a post hook that will be called after other middlewares are
	 * applied. Hooks can be async functions and will be called in series.
	 */
	configurePreviewServer?: ObjectHook<PreviewServerHook>;
	/**
	 * Run logic when the server is restarted or closed. The hook receives a
	 * `reason` that is `'restart'` when the server is restarting and `'close'`
	 * when it is closing.
	 *
	 * The hooks are called after the server is torn down. Hooks can be async
	 * functions and will be called in parallel.
	 */
	closeServer?: ObjectHook<CloseServerHook>;
	/**
	 * Same as `closeServer` but for the preview server. The preview server never
	 * restarts, so no `reason` is provided.
	 */
	closePreviewServer?: ObjectHook<ClosePreviewServerHook>;
	/**
	 * Transform index.html.
	 * The hook receives the following arguments:
	 *
	 * - html: string
	 * - ctx: IndexHtmlTransformContext, which contains:
	 *    - path: public path when served
	 *    - filename: filename on disk
	 *    - server?: ViteDevServer (only present during serve)
	 *    - bundle?: rollup.OutputBundle (only present during build)
	 *    - chunk?: rollup.OutputChunk
	 *    - originalUrl?: string
	 *
	 * It can either return a transformed string, or a list of html tag
	 * descriptors that will be injected into the `<head>` or `<body>`.
	 *
	 * By default the transform is applied **after** vite's internal html
	 * transform. If you need to apply the transform before vite, use an object:
	 * `{ order: 'pre', handler: hook }`
	 */
	transformIndexHtml?: IndexHtmlTransform;
	/**
	 * Build Environments
	 *
	 * @experimental
	 */
	buildApp?: ObjectHook<BuildAppHook>;
	/**
	 * Perform custom handling of HMR updates.
	 * The handler receives a context containing changed filename, timestamp, a
	 * list of modules affected by the file change, and the dev server instance.
	 *
	 * - The hook can return a filtered list of modules to narrow down the update.
	 *   e.g. for a Vue SFC, we can narrow down the part to update by comparing
	 *   the descriptors.
	 *
	 * - The hook can also return an empty array and then perform custom updates
	 *   by sending a custom hmr payload via server.ws.send().
	 *
	 * - If the hook doesn't return a value, the hmr update will be performed as
	 *   normal.
	 */
	handleHotUpdate?: ObjectHook<
		(
			this: MinimalPluginContextWithoutEnvironment,
			ctx: HmrContext,
		) =>
			| Array<ModuleNode>
			| void
			| Promise<Array<ModuleNode> | void>
	>;

	/**
	 * This hook is not supported by Rolldown yet. But the type is declared for compatibility.
	 *
	 * @deprecated This hook is **not** deprecated. It is marked as deprecated just to make it clear that this hook is currently a no-op.
	 */
	shouldTransformCachedModule?: ObjectHook<
		(
			this: PluginContext,
			options: {
				code: string;
				id: string;
				meta: CustomPluginOptions;
				moduleSideEffects: boolean | "no-treeshake";
			},
		) => boolean | null | void
	>;
}

export type HookHandler<T> =
	T extends ObjectHook<infer H> ? H : T;

export type PluginWithRequiredHook<K extends keyof Plugin> =
	Plugin & {
		[P in K]: NonNullable<Plugin[P]>;
	};

type Thenable<T> = T | Promise<T>;

export type FalsyPlugin = false | null | undefined;

export type PluginOption = Thenable<
	| Plugin
	| { name: string } // for rollup plugin compatibility
	| FalsyPlugin
	| PluginOption[]
>;

const ignoredEnvironmentPluginHooks = [
	"config",
	"configEnvironment",
	"configureServer",
	"configResolved",
] as const;

export async function resolveEnvironmentPlugins(
	environment: PartialEnvironment,
): Promise<Plugin[]> {
	const environmentPlugins: Plugin[] = [];
	for (const plugin of environment.getTopLevelConfig()
		.plugins) {
		if (plugin.applyToEnvironment) {
			const applied =
				await plugin.applyToEnvironment(environment);
			if (!applied) {
				continue;
			}
			if (applied !== true) {
				const appliedPlugins = (
					await asyncFlatten(arraify(applied))
				).filter(Boolean) as Plugin[];
				for (const appliedPlugin of appliedPlugins) {
					const ignoredHooks =
						ignoredEnvironmentPluginHooks.filter(
							(hook) => appliedPlugin[hook],
						);
					if (ignoredHooks.length > 0) {
						environment.logger.warnOnce(
							`Plugin "${appliedPlugin.name}" defines Vite-specific hooks (${ignoredHooks.join(", ")}) in a plugin returned from applyToEnvironment. These hooks will be ignored.`,
						);
					}
				}
				environmentPlugins.push(...appliedPlugins);
				continue;
			}
		}
		environmentPlugins.push(plugin);
	}
	return environmentPlugins;
}

/**
 * @experimental
 */
export function perEnvironmentPlugin(
	name: string,
	applyToEnvironment: (
		environment: PartialEnvironment,
	) => boolean | Promise<boolean> | PluginOption,
): Plugin {
	return {
		name,
		applyToEnvironment,
	};
}
